/* SergioLearns — visualizador de algoritmos: motor (window.SLAlg).
 * El programa del lector lo ejecuta CPython de verdad (Pyodide 314.0.7, la versión del entorno de Python) en un worker,
 * trazado con sys.settrace por arnes.py: cada paso trae la línea, la pila, las listas y las comparaciones.
 * "# SergioLearns — visualizador de algoritmos: arnés de Python (se ejecuta con Pyodide, CPython de verdad).\n# sl_traza(json) -> json. Ejecuta el programa del lector con sys.settrace y devuelve los pasos:\n#   línea que va a ejecutarse, pila de llamadas con sus variables, listas (con la identidad de cada elemento),\n#   comparaciones hechas desde el paso anterior (las registra el propio elemento: SLInt/SLFloat/SLStr),\n#   llamadas y valores devueltos (para el árbol) y lo que lleva escrito print().\n# Los números de las listas literales del programa ([5, 2, 9]) se envuelven en SLInt/SLFloat/SLStr con ast:\n# siguen siendo int/float/str de verdad (isinstance, aritmética, print, sort), pero cada uno sabe quién es.\nimport ast, io, json, sys\n\nFN = '<sl>'\nMAXL = 48        # elementos que se enseñan de una lista\nMAXR = 70        # caracteres del repr de un valor\n\n\nclass _Rec:\n    def __init__(self):\n        self.cmp = []\n        self.on = False\n\n\nR = _Rec()\n\n\ndef _k(x):\n    return getattr(x, '_sl', None)\n\n\ndef _mk(base, op, sym):\n    f = getattr(base, op)\n\n    def m(self, o):\n        r = f(self, o)\n        if R.on and r is not NotImplemented:\n            R.cmp.append([_k(self), _k(o), sym, _pv(self), _pv(o), bool(r)])\n        return r\n    return m\n\n\ndef _cls(base, name):\n    d = {'__hash__': base.__hash__}\n    for op, sym in (('__lt__', '<'), ('__le__', '<='), ('__gt__', '>'), ('__ge__', '>='), ('__eq__', '=='), ('__ne__', '!=')):\n        d[op] = _mk(base, op, sym)\n    d['__repr__'] = lambda self: base.__repr__(self)\n    d['__str__'] = lambda self: base.__str__(self)\n    d['__format__'] = lambda self, spec: base.__format__(base(self), spec)\n    d['__reduce__'] = lambda self: (base, (base(self),))\n    return type(name, (base,), d)\n\n\nSLInt = _cls(int, 'int')\nSLFloat = _cls(float, 'float')\nSLStr = _cls(str, 'str')\n_seq = [0]\n\n\ndef _wrap(v):\n    if isinstance(v, bool) or _k(v) is not None:\n        return v\n    if isinstance(v, int):\n        t = SLInt\n    elif isinstance(v, float):\n        t = SLFloat\n    elif isinstance(v, str):\n        t = SLStr\n    else:\n        return v\n    o = t(v)\n    _seq[0] += 1\n    o._sl = _seq[0]\n    return o\n\n\ndef __sl_l(xs):\n    return [_wrap(x) for x in xs]\n\n\nclass _Tr(ast.NodeTransformer):\n    # [5, 2, -3, 7.5, 'Ana'] -> __sl_l([...]) (solo listas literales de constantes)\n    def visit_List(self, node):\n        self.generic_visit(node)\n        if not node.elts or not isinstance(node.ctx, ast.Load):\n            return node\n        for e in node.elts:\n            if isinstance(e, ast.Constant) and isinstance(e.value, (int, float, str)) and not isinstance(e.value, bool):\n                continue\n            if isinstance(e, ast.UnaryOp) and isinstance(e.op, ast.USub) and isinstance(e.operand, ast.Constant) and isinstance(e.operand.value, (int, float)):\n                continue\n            return node\n        return ast.copy_location(ast.Call(func=ast.Name('__sl_l', ast.Load()), args=[node], keywords=[]), node)\n\n\ndef _pv(v):\n    if isinstance(v, bool) or v is None:\n        return repr(v)\n    if isinstance(v, (int, float)):\n        return repr(type(v).__mro__[-2](v)) if _k(v) is not None else repr(v)\n    if isinstance(v, str):\n        return repr(str(v))\n    return None\n\n\nclass Stop(Exception):\n    pass\n\n\nclass SinEntrada(Exception):\n    pass\n\n\ndef _short(v):\n    try:\n        if isinstance(v, (list, tuple)):\n            b = '[]' if isinstance(v, list) else '()'\n            parts = []\n            for x in v[:8]:\n                p = _pv(x)\n                parts.append(p if p is not None else _short(x))\n            s = b[0] + ', '.join(parts) + (', …' if len(v) > 8 else '') + (',' if isinstance(v, tuple) and len(v) == 1 else '') + b[1]\n        else:\n            p = _pv(v)\n            s = p if p is not None else repr(v)\n    except Exception:\n        s = '?'\n    return s if len(s) <= MAXR else s[:MAXR - 1] + '…'\n\n\ndef sl_traza(q):\n    q = json.loads(q)\n    code = q['code']\n    maxs = int(q.get('max', 4000))\n    _seq[0] = 0\n    R.cmp = []\n    R.on = False\n    out = io.StringIO()\n    res = {'steps': [], 'calls': [], 'out': '', 'err': None, 'cut': False}\n    try:\n        tree = ast.parse(code, FN)\n    except SyntaxError as e:\n        res['err'] = {'t': 'SyntaxError', 'm': e.msg, 'l': e.lineno or 0, 'c': e.offset or 0}\n        return json.dumps(res)\n    tree = ast.fix_missing_locations(_Tr().visit(tree))\n    try:\n        cobj = compile(tree, FN, 'exec')\n    except SyntaxError as e:\n        res['err'] = {'t': 'SyntaxError', 'm': e.msg, 'l': e.lineno or 0, 'c': e.offset or 0}\n        return json.dumps(res)\n\n    def _sin_entrada(*a):\n        raise SinEntrada('input()')\n    g = {'__name__': '__main__', '__builtins__': __builtins__, '__sl_l': __sl_l, 'input': _sin_entrada}\n    lids = {}       # id(lista) -> número\n    keep = []       # mantiene vivas las listas vistas (que no se reutilice su id)\n    lastc = {}      # número -> contenido enviado la última vez\n    fid = {}        # id(frame) -> nodo del árbol\n    nodes = res['calls']\n    steps = res['steps']\n    st = {'n': 0}\n\n    def lref(v):\n        i = lids.get(id(v))\n        if i is None:\n            i = len(lids) + 1\n            lids[id(v)] = i\n            keep.append(v)\n        return i\n\n    def val(v):\n        if isinstance(v, list) and all(isinstance(x, (int, float, str)) and not isinstance(x, bool) for x in v[:MAXL]):\n            return {'L': lref(v)}\n        return _short(v)\n\n    def frames(f):\n        fs = []\n        while f is not None:\n            if f.f_code.co_filename == FN:\n                fs.append(f)\n            f = f.f_back\n        fs.reverse()\n        return fs\n\n    def snap(f, ev, extra=None, fs=None):\n        if f is not None:\n            if st['n'] >= maxs:\n                res['cut'] = True\n                raise Stop()\n            fs = frames(f)\n        st['n'] += 1\n        stack = []\n        seen = set()\n        for fr in fs:\n            if fr.f_code.co_name == '<module>':\n                loc = {k: v for k, v in fr.f_locals.items() if not k.startswith('__') and not callable(v) and not isinstance(v, type(sys))}\n                name = None\n            else:\n                loc = dict(fr.f_locals)\n                name = fr.f_code.co_name\n            vs = []\n            for k, v in loc.items():\n                vs.append([k, val(v)])\n                if isinstance(v, list):\n                    seen.add(id(v))\n            stack.append({'f': name, 'v': vs, 'n': fid.get(id(fr))})\n        # contenido de las listas que han cambiado\n        ch = {}\n        for i, lst in enumerate(keep):\n            n = lids[id(lst)]\n            c = [[_k(x), _pv(x) if _pv(x) is not None else _short(x)] for x in lst[:MAXL]]\n            if len(lst) > MAXL:\n                c.append([None, '…'])\n            if lastc.get(n) != c:\n                lastc[n] = c\n                ch[n] = c\n        s = {'l': f.f_lineno if f is not None else (extra or {}).get('l', 0), 'e': ev, 's': stack, 'o': len(out.getvalue())}\n        if ch:\n            s['c'] = ch\n        if R.cmp:\n            s['k'] = R.cmp\n            R.cmp = []\n        if extra:\n            s.update(extra)\n        steps.append(s)\n\n    def tracer(f, ev, arg):\n        if f.f_code.co_filename != FN:\n            return None\n        R.on = False\n        try:\n            if ev == 'call':\n                if not f.f_code.co_name.startswith('<'):\n                    par = None\n                    b = f.f_back\n                    while b is not None and b.f_code.co_filename != FN:\n                        b = b.f_back\n                    if b is not None:\n                        par = fid.get(id(b))\n                    a = [[k, _short(f.f_locals[k])] for k in f.f_code.co_varnames[:f.f_code.co_argcount] if k in f.f_locals]\n                    nid = len(nodes)\n                    nodes.append({'f': f.f_code.co_name, 'a': a, 'p': par, 's': st['n'], 'r': None, 'e': None})\n                    fid[id(f)] = nid\n                    snap(f, 'call', {'n': nid})\n            elif ev == 'line':\n                snap(f, 'line')\n            elif ev == 'return':\n                nid = fid.get(id(f))\n                if nid is not None:\n                    nodes[nid]['r'] = _short(arg)\n                    snap(f, 'ret', {'n': nid, 'r': _short(arg)})\n                    nodes[nid]['e'] = st['n'] - 1\n        finally:\n            R.on = True\n        return tracer\n\n    old = sys.stdout\n    sys.stdout = out\n    lim = sys.getrecursionlimit()\n    sys.setrecursionlimit(150)\n    try:\n        sys.settrace(tracer)\n        R.on = True\n        exec(cobj, g)\n    except Stop:\n        pass\n    except BaseException as e:\n        tb = sys.exc_info()[2]\n        res['err'] = {'t': type(e).__name__, 'm': 'maximum recursion depth exceeded' if isinstance(e, RecursionError) else str(e), 'l': _errline(tb), 'c': 0}\n        tbs = []\n        while tb is not None:\n            if tb.tb_frame.f_code.co_filename == FN:\n                tbs.append(tb.tb_frame)\n            tb = tb.tb_next\n        res['_fs'] = tbs[:60] + tbs[-20:] if len(tbs) > 80 else tbs\n    finally:\n        sys.settrace(None)\n        R.on = False\n        sys.stdout = old\n        sys.setrecursionlimit(lim)\n    # paso final: cómo queda todo al terminar (o en el error)\n    if not res['cut']:\n        try:\n            if res['err']:\n                fs = res.pop('_fs', None) or []\n                snap(None, 'err', {'l': res['err']['l']}, fs)\n            else:\n                class _M:\n                    pass\n                m = _M()\n                m.f_locals = g\n                m.f_code = type('C', (), {'co_name': '<module>'})()\n                snap(None, 'end', {'l': 0}, [m])\n        except Exception:\n            pass\n    res.pop('_fs', None)\n    res['out'] = out.getvalue()[:20000]\n    return json.dumps(res, ensure_ascii=False)\n\n\ndef _errline(tb):\n    # la línea más profunda del programa (si es la del def, la de la llamada: pasa con RecursionError)\n    ls = []\n    while tb is not None:\n        if tb.tb_frame.f_code.co_filename == FN:\n            ls.append((tb.tb_lineno, tb.tb_frame.f_code.co_firstlineno, tb.tb_frame.f_code.co_name))\n        tb = tb.tb_next\n    for ln, first, name in reversed(ls):\n        if not (ln == first and name != '<module>'):\n            return ln\n    return ls[-1][0] if ls else 0\n" y [{"k": "busqueda-lineal", "c": "bus", "n": ["Búsqueda lineal", "Linear search"], "p": [["notas", "marks", "list"], ["buscado", "target", "int"]], "s": false, "py": ["def buscar(lista, buscado):\n    for i in range(len(lista)):\n        if lista[i] == buscado:\n            return i\n    return -1\n\n\nnotas = [7, 3, 9, 5, 10, 4, 8, 6]\nbuscado = 10\nprint(\"Está en la posición\", buscar(notas, buscado))\n", "def find(items, target):\n    for i in range(len(items)):\n        if items[i] == target:\n            return i\n    return -1\n\n\nmarks = [7, 3, 9, 5, 10, 4, 8, 6]\ntarget = 10\nprint(\"Found at position\", find(marks, target))\n"], "java": ["public class Main {\n    static int buscar(int[] lista, int buscado) {\n        for (int i = 0; i < lista.length; i++) {\n            if (lista[i] == buscado) {\n                return i;\n            }\n        }\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        int[] notas = {7, 3, 9, 5, 10, 4, 8, 6};\n        int buscado = 10;\n        System.out.println(\"Está en la posición \" + buscar(notas, buscado));\n    }\n}\n", "public class Main {\n    static int find(int[] items, int target) {\n        for (int i = 0; i < items.length; i++) {\n            if (items[i] == target) {\n                return i;\n            }\n        }\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        int[] marks = {7, 3, 9, 5, 10, 4, 8, 6};\n        int target = 10;\n        System.out.println(\"Found at position \" + find(marks, target));\n    }\n}\n"]}, {"k": "busqueda-binaria", "c": "bus", "n": ["Búsqueda binaria (iterativa)", "Binary search (iterative)"], "p": [["turnos", "tickets", "list"], ["buscado", "target", "int"]], "s": true, "py": ["def busqueda_binaria(lista, buscado):\n    inf = 0\n    sup = len(lista) - 1\n    while inf <= sup:\n        medio = (inf + sup) // 2\n        if lista[medio] == buscado:\n            return medio\n        elif lista[medio] < buscado:\n            inf = medio + 1\n        else:\n            sup = medio - 1\n    return -1\n\n\nturnos = [3, 8, 12, 17, 23, 31, 38, 44, 52, 58, 61, 70, 77, 85, 90]\nbuscado = 58\nprint(\"Turno en la posición\", busqueda_binaria(turnos, buscado))\n", "def binary_search(items, target):\n    low = 0\n    high = len(items) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if items[mid] == target:\n            return mid\n        elif items[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1\n\n\ntickets = [3, 8, 12, 17, 23, 31, 38, 44, 52, 58, 61, 70, 77, 85, 90]\ntarget = 58\nprint(\"Ticket at position\", binary_search(tickets, target))\n"], "java": ["public class Main {\n    static int busquedaBinaria(int[] lista, int buscado) {\n        int inf = 0;\n        int sup = lista.length - 1;\n        while (inf <= sup) {\n            int medio = (inf + sup) / 2;\n            if (lista[medio] == buscado) {\n                return medio;\n            } else if (lista[medio] < buscado) {\n                inf = medio + 1;\n            } else {\n                sup = medio - 1;\n            }\n        }\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        int[] turnos = {3, 8, 12, 17, 23, 31, 38, 44, 52, 58, 61, 70, 77, 85, 90};\n        int buscado = 58;\n        System.out.println(\"Turno en la posición \" + busquedaBinaria(turnos, buscado));\n    }\n}\n", "public class Main {\n    static int binarySearch(int[] items, int target) {\n        int low = 0;\n        int high = items.length - 1;\n        while (low <= high) {\n            int mid = (low + high) / 2;\n            if (items[mid] == target) {\n                return mid;\n            } else if (items[mid] < target) {\n                low = mid + 1;\n            } else {\n                high = mid - 1;\n            }\n        }\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        int[] tickets = {3, 8, 12, 17, 23, 31, 38, 44, 52, 58, 61, 70, 77, 85, 90};\n        int target = 58;\n        System.out.println(\"Ticket at position \" + binarySearch(tickets, target));\n    }\n}\n"]}, {"k": "binaria-recursiva", "c": "bus", "n": ["Búsqueda binaria recursiva (inmersión)", "Recursive binary search (helper with bounds)"], "p": [["turnos", "tickets", "list"], ["buscado", "target", "int"]], "s": true, "py": ["def buscar(lista, buscado):\n    return buscar_entre(lista, buscado, 0, len(lista) - 1)\n\n\ndef buscar_entre(lista, buscado, inf, sup):\n    if inf > sup:\n        return -1\n    medio = (inf + sup) // 2\n    if lista[medio] == buscado:\n        return medio\n    if lista[medio] < buscado:\n        return buscar_entre(lista, buscado, medio + 1, sup)\n    return buscar_entre(lista, buscado, inf, medio - 1)\n\n\nturnos = [3, 8, 12, 17, 23, 31, 38, 44, 52, 58, 61, 70, 77, 85, 90]\nbuscado = 17\nprint(\"Turno en la posición\", buscar(turnos, buscado))\n", "def find(items, target):\n    return find_between(items, target, 0, len(items) - 1)\n\n\ndef find_between(items, target, low, high):\n    if low > high:\n        return -1\n    mid = (low + high) // 2\n    if items[mid] == target:\n        return mid\n    if items[mid] < target:\n        return find_between(items, target, mid + 1, high)\n    return find_between(items, target, low, mid - 1)\n\n\ntickets = [3, 8, 12, 17, 23, 31, 38, 44, 52, 58, 61, 70, 77, 85, 90]\ntarget = 17\nprint(\"Ticket at position\", find(tickets, target))\n"], "java": ["public class Main {\n    static int buscar(int[] lista, int buscado) {\n        return buscarEntre(lista, buscado, 0, lista.length - 1);\n    }\n\n    static int buscarEntre(int[] lista, int buscado, int inf, int sup) {\n        if (inf > sup) {\n            return -1;\n        }\n        int medio = (inf + sup) / 2;\n        if (lista[medio] == buscado) {\n            return medio;\n        }\n        if (lista[medio] < buscado) {\n            return buscarEntre(lista, buscado, medio + 1, sup);\n        }\n        return buscarEntre(lista, buscado, inf, medio - 1);\n    }\n\n    public static void main(String[] args) {\n        int[] turnos = {3, 8, 12, 17, 23, 31, 38, 44, 52, 58, 61, 70, 77, 85, 90};\n        int buscado = 17;\n        System.out.println(\"Turno en la posición \" + buscar(turnos, buscado));\n    }\n}\n", "public class Main {\n    static int find(int[] items, int target) {\n        return findBetween(items, target, 0, items.length - 1);\n    }\n\n    static int findBetween(int[] items, int target, int low, int high) {\n        if (low > high) {\n            return -1;\n        }\n        int mid = (low + high) / 2;\n        if (items[mid] == target) {\n            return mid;\n        }\n        if (items[mid] < target) {\n            return findBetween(items, target, mid + 1, high);\n        }\n        return findBetween(items, target, low, mid - 1);\n    }\n\n    public static void main(String[] args) {\n        int[] tickets = {3, 8, 12, 17, 23, 31, 38, 44, 52, 58, 61, 70, 77, 85, 90};\n        int target = 17;\n        System.out.println(\"Ticket at position \" + find(tickets, target));\n    }\n}\n"]}, {"k": "factorial", "c": "rec", "n": ["Factorial", "Factorial"], "p": [["n", "n", "int"]], "s": false, "py": ["def factorial(n):\n    if n == 0:\n        return 1\n    return n * factorial(n - 1)\n\n\nn = 5\nprint(f\"{n}! = {factorial(n)}\")\n", "def factorial(n):\n    if n == 0:\n        return 1\n    return n * factorial(n - 1)\n\n\nn = 5\nprint(f\"{n}! = {factorial(n)}\")\n"], "java": ["public class Main {\n    static long factorial(int n) {\n        if (n == 0) {\n            return 1;\n        }\n        return n * factorial(n - 1);\n    }\n\n    public static void main(String[] args) {\n        int n = 5;\n        System.out.println(n + \"! = \" + factorial(n));\n    }\n}\n", "public class Main {\n    static long factorial(int n) {\n        if (n == 0) {\n            return 1;\n        }\n        return n * factorial(n - 1);\n    }\n\n    public static void main(String[] args) {\n        int n = 5;\n        System.out.println(n + \"! = \" + factorial(n));\n    }\n}\n"]}, {"k": "potencia-doble", "c": "rec", "n": ["Potencia: dos llamadas por nivel", "Power: two calls per level"], "p": [["base", "base", "int"], ["exp", "exp", "int"]], "s": false, "py": ["def potencia(base, exp):\n    if exp == 0:\n        return 1\n    if exp == 1:\n        return base\n    mitad = exp // 2\n    return potencia(base, mitad) * potencia(base, exp - mitad)\n\n\nbase = 2\nexp = 8\nprint(f\"{base}^{exp} = {potencia(base, exp)}\")\n", "def power(base, exp):\n    if exp == 0:\n        return 1\n    if exp == 1:\n        return base\n    half = exp // 2\n    return power(base, half) * power(base, exp - half)\n\n\nbase = 2\nexp = 8\nprint(f\"{base}^{exp} = {power(base, exp)}\")\n"], "java": ["public class Main {\n    static long potencia(long base, int exp) {\n        if (exp == 0) {\n            return 1;\n        }\n        if (exp == 1) {\n            return base;\n        }\n        int mitad = exp / 2;\n        return potencia(base, mitad) * potencia(base, exp - mitad);\n    }\n\n    public static void main(String[] args) {\n        long base = 2;\n        int exp = 8;\n        System.out.println(base + \"^\" + exp + \" = \" + potencia(base, exp));\n    }\n}\n", "public class Main {\n    static long power(long base, int exp) {\n        if (exp == 0) {\n            return 1;\n        }\n        if (exp == 1) {\n            return base;\n        }\n        int half = exp / 2;\n        return power(base, half) * power(base, exp - half);\n    }\n\n    public static void main(String[] args) {\n        long base = 2;\n        int exp = 8;\n        System.out.println(base + \"^\" + exp + \" = \" + power(base, exp));\n    }\n}\n"]}, {"k": "potencia-rapida", "c": "rec", "n": ["Potencia rápida: una llamada por nivel", "Fast power: one call per level"], "p": [["base", "base", "int"], ["exp", "exp", "int"]], "s": false, "py": ["def potencia(base, exp):\n    if exp == 0:\n        return 1\n    mitad = potencia(base, exp // 2)\n    if exp % 2 == 0:\n        return mitad * mitad\n    return mitad * mitad * base\n\n\nbase = 2\nexp = 8\nprint(f\"{base}^{exp} = {potencia(base, exp)}\")\n", "def power(base, exp):\n    if exp == 0:\n        return 1\n    half = power(base, exp // 2)\n    if exp % 2 == 0:\n        return half * half\n    return half * half * base\n\n\nbase = 2\nexp = 8\nprint(f\"{base}^{exp} = {power(base, exp)}\")\n"], "java": ["public class Main {\n    static long potencia(long base, int exp) {\n        if (exp == 0) {\n            return 1;\n        }\n        long mitad = potencia(base, exp / 2);\n        if (exp % 2 == 0) {\n            return mitad * mitad;\n        }\n        return mitad * mitad * base;\n    }\n\n    public static void main(String[] args) {\n        long base = 2;\n        int exp = 8;\n        System.out.println(base + \"^\" + exp + \" = \" + potencia(base, exp));\n    }\n}\n", "public class Main {\n    static long power(long base, int exp) {\n        if (exp == 0) {\n            return 1;\n        }\n        long half = power(base, exp / 2);\n        if (exp % 2 == 0) {\n            return half * half;\n        }\n        return half * half * base;\n    }\n\n    public static void main(String[] args) {\n        long base = 2;\n        int exp = 8;\n        System.out.println(base + \"^\" + exp + \" = \" + power(base, exp));\n    }\n}\n"]}, {"k": "fibonacci", "c": "rec", "n": ["Fibonacci (el árbol que se repite)", "Fibonacci (the tree that repeats itself)"], "p": [["n", "n", "int"]], "s": false, "py": ["def fibonacci(n):\n    if n < 2:\n        return n\n    return fibonacci(n - 1) + fibonacci(n - 2)\n\n\nn = 5\nprint(f\"fibonacci({n}) = {fibonacci(n)}\")\n", "def fibonacci(n):\n    if n < 2:\n        return n\n    return fibonacci(n - 1) + fibonacci(n - 2)\n\n\nn = 5\nprint(f\"fibonacci({n}) = {fibonacci(n)}\")\n"], "java": ["public class Main {\n    static long fibonacci(int n) {\n        if (n < 2) {\n            return n;\n        }\n        return fibonacci(n - 1) + fibonacci(n - 2);\n    }\n\n    public static void main(String[] args) {\n        int n = 5;\n        System.out.println(\"fibonacci(\" + n + \") = \" + fibonacci(n));\n    }\n}\n", "public class Main {\n    static long fibonacci(int n) {\n        if (n < 2) {\n            return n;\n        }\n        return fibonacci(n - 1) + fibonacci(n - 2);\n    }\n\n    public static void main(String[] args) {\n        int n = 5;\n        System.out.println(\"fibonacci(\" + n + \") = \" + fibonacci(n));\n    }\n}\n"]}, {"k": "hanoi", "c": "rec", "n": ["Torres de Hanói", "Towers of Hanoi"], "p": [["n", "n", "int"]], "s": false, "py": ["def hanoi(n, origen, destino, auxiliar):\n    if n == 0:\n        return\n    hanoi(n - 1, origen, auxiliar, destino)\n    print(\"Disco\", n, \"de\", origen, \"a\", destino)\n    hanoi(n - 1, auxiliar, destino, origen)\n\n\nn = 3\nhanoi(n, \"A\", \"C\", \"B\")\n", "def hanoi(n, source, dest, spare):\n    if n == 0:\n        return\n    hanoi(n - 1, source, spare, dest)\n    print(\"Disk\", n, \"from\", source, \"to\", dest)\n    hanoi(n - 1, spare, dest, source)\n\n\nn = 3\nhanoi(n, \"A\", \"C\", \"B\")\n"], "java": ["public class Main {\n    static void hanoi(int n, String origen, String destino, String auxiliar) {\n        if (n == 0) {\n            return;\n        }\n        hanoi(n - 1, origen, auxiliar, destino);\n        System.out.println(\"Disco \" + n + \" de \" + origen + \" a \" + destino);\n        hanoi(n - 1, auxiliar, destino, origen);\n    }\n\n    public static void main(String[] args) {\n        int n = 3;\n        hanoi(n, \"A\", \"C\", \"B\");\n    }\n}\n", "public class Main {\n    static void hanoi(int n, String source, String dest, String spare) {\n        if (n == 0) {\n            return;\n        }\n        hanoi(n - 1, source, spare, dest);\n        System.out.println(\"Disk \" + n + \" from \" + source + \" to \" + dest);\n        hanoi(n - 1, spare, dest, source);\n    }\n\n    public static void main(String[] args) {\n        int n = 3;\n        hanoi(n, \"A\", \"C\", \"B\");\n    }\n}\n"]}, {"k": "burbuja", "c": "ord", "n": ["Burbuja", "Bubble sort"], "p": [["notas", "marks", "list"]], "s": false, "py": ["def burbuja(lista):\n    n = len(lista)\n    for vuelta in range(n - 1):\n        hubo_cambio = False\n        for j in range(n - 1 - vuelta):\n            if lista[j] > lista[j + 1]:\n                lista[j], lista[j + 1] = lista[j + 1], lista[j]\n                hubo_cambio = True\n        if not hubo_cambio:\n            break\n\n\nnotas = [7, 3, 9, 5, 10, 4, 8, 6]\nburbuja(notas)\nprint(notas)\n", "def bubble_sort(items):\n    n = len(items)\n    for lap in range(n - 1):\n        swapped = False\n        for j in range(n - 1 - lap):\n            if items[j] > items[j + 1]:\n                items[j], items[j + 1] = items[j + 1], items[j]\n                swapped = True\n        if not swapped:\n            break\n\n\nmarks = [7, 3, 9, 5, 10, 4, 8, 6]\nbubble_sort(marks)\nprint(marks)\n"], "java": ["import java.util.Arrays;\n\npublic class Main {\n    static void burbuja(int[] lista) {\n        int n = lista.length;\n        for (int vuelta = 0; vuelta < n - 1; vuelta++) {\n            boolean huboCambio = false;\n            for (int j = 0; j < n - 1 - vuelta; j++) {\n                if (lista[j] > lista[j + 1]) {\n                    int aux = lista[j];\n                    lista[j] = lista[j + 1];\n                    lista[j + 1] = aux;\n                    huboCambio = true;\n                }\n            }\n            if (!huboCambio) {\n                break;\n            }\n        }\n    }\n\n    public static void main(String[] args) {\n        int[] notas = {7, 3, 9, 5, 10, 4, 8, 6};\n        burbuja(notas);\n        System.out.println(Arrays.toString(notas));\n    }\n}\n", "import java.util.Arrays;\n\npublic class Main {\n    static void bubbleSort(int[] items) {\n        int n = items.length;\n        for (int lap = 0; lap < n - 1; lap++) {\n            boolean swapped = false;\n            for (int j = 0; j < n - 1 - lap; j++) {\n                if (items[j] > items[j + 1]) {\n                    int tmp = items[j];\n                    items[j] = items[j + 1];\n                    items[j + 1] = tmp;\n                    swapped = true;\n                }\n            }\n            if (!swapped) {\n                break;\n            }\n        }\n    }\n\n    public static void main(String[] args) {\n        int[] marks = {7, 3, 9, 5, 10, 4, 8, 6};\n        bubbleSort(marks);\n        System.out.println(Arrays.toString(marks));\n    }\n}\n"]}, {"k": "seleccion", "c": "ord", "n": ["Selección", "Selection sort"], "p": [["notas", "marks", "list"]], "s": false, "py": ["def seleccion(lista):\n    n = len(lista)\n    for i in range(n - 1):\n        i_min = i\n        for j in range(i + 1, n):\n            if lista[j] < lista[i_min]:\n                i_min = j\n        lista[i], lista[i_min] = lista[i_min], lista[i]\n\n\nnotas = [7, 3, 9, 5, 10, 4, 8, 6]\nseleccion(notas)\nprint(notas)\n", "def selection_sort(items):\n    n = len(items)\n    for i in range(n - 1):\n        i_min = i\n        for j in range(i + 1, n):\n            if items[j] < items[i_min]:\n                i_min = j\n        items[i], items[i_min] = items[i_min], items[i]\n\n\nmarks = [7, 3, 9, 5, 10, 4, 8, 6]\nselection_sort(marks)\nprint(marks)\n"], "java": ["import java.util.Arrays;\n\npublic class Main {\n    static void seleccion(int[] lista) {\n        int n = lista.length;\n        for (int i = 0; i < n - 1; i++) {\n            int iMin = i;\n            for (int j = i + 1; j < n; j++) {\n                if (lista[j] < lista[iMin]) {\n                    iMin = j;\n                }\n            }\n            int aux = lista[i];\n            lista[i] = lista[iMin];\n            lista[iMin] = aux;\n        }\n    }\n\n    public static void main(String[] args) {\n        int[] notas = {7, 3, 9, 5, 10, 4, 8, 6};\n        seleccion(notas);\n        System.out.println(Arrays.toString(notas));\n    }\n}\n", "import java.util.Arrays;\n\npublic class Main {\n    static void selectionSort(int[] items) {\n        int n = items.length;\n        for (int i = 0; i < n - 1; i++) {\n            int iMin = i;\n            for (int j = i + 1; j < n; j++) {\n                if (items[j] < items[iMin]) {\n                    iMin = j;\n                }\n            }\n            int tmp = items[i];\n            items[i] = items[iMin];\n            items[iMin] = tmp;\n        }\n    }\n\n    public static void main(String[] args) {\n        int[] marks = {7, 3, 9, 5, 10, 4, 8, 6};\n        selectionSort(marks);\n        System.out.println(Arrays.toString(marks));\n    }\n}\n"]}, {"k": "insercion", "c": "ord", "n": ["Inserción", "Insertion sort"], "p": [["notas", "marks", "list"]], "s": false, "py": ["def insercion(lista):\n    for i in range(1, len(lista)):\n        clave = lista[i]\n        j = i - 1\n        while j >= 0 and lista[j] > clave:\n            lista[j + 1] = lista[j]\n            j = j - 1\n        lista[j + 1] = clave\n\n\nnotas = [7, 3, 9, 5, 10, 4, 8, 6]\ninsercion(notas)\nprint(notas)\n", "def insertion_sort(items):\n    for i in range(1, len(items)):\n        key = items[i]\n        j = i - 1\n        while j >= 0 and items[j] > key:\n            items[j + 1] = items[j]\n            j = j - 1\n        items[j + 1] = key\n\n\nmarks = [7, 3, 9, 5, 10, 4, 8, 6]\ninsertion_sort(marks)\nprint(marks)\n"], "java": ["import java.util.Arrays;\n\npublic class Main {\n    static void insercion(int[] lista) {\n        for (int i = 1; i < lista.length; i++) {\n            int clave = lista[i];\n            int j = i - 1;\n            while (j >= 0 && lista[j] > clave) {\n                lista[j + 1] = lista[j];\n                j = j - 1;\n            }\n            lista[j + 1] = clave;\n        }\n    }\n\n    public static void main(String[] args) {\n        int[] notas = {7, 3, 9, 5, 10, 4, 8, 6};\n        insercion(notas);\n        System.out.println(Arrays.toString(notas));\n    }\n}\n", "import java.util.Arrays;\n\npublic class Main {\n    static void insertionSort(int[] items) {\n        for (int i = 1; i < items.length; i++) {\n            int key = items[i];\n            int j = i - 1;\n            while (j >= 0 && items[j] > key) {\n                items[j + 1] = items[j];\n                j = j - 1;\n            }\n            items[j + 1] = key;\n        }\n    }\n\n    public static void main(String[] args) {\n        int[] marks = {7, 3, 9, 5, 10, 4, 8, 6};\n        insertionSort(marks);\n        System.out.println(Arrays.toString(marks));\n    }\n}\n"]}, {"k": "mezcla", "c": "ava", "n": ["Mezcla (mergesort)", "Merge sort"], "p": [["notas", "marks", "list"]], "s": false, "py": ["def ordenar_mezcla(lista):\n    if len(lista) <= 1:\n        return lista\n    medio = len(lista) // 2\n    izq = ordenar_mezcla(lista[:medio])\n    der = ordenar_mezcla(lista[medio:])\n    return mezclar(izq, der)\n\n\ndef mezclar(izq, der):\n    resultado = []\n    i = 0\n    j = 0\n    while i < len(izq) and j < len(der):\n        if izq[i] <= der[j]:\n            resultado.append(izq[i])\n            i = i + 1\n        else:\n            resultado.append(der[j])\n            j = j + 1\n    resultado.extend(izq[i:])\n    resultado.extend(der[j:])\n    return resultado\n\n\nnotas = [7, 3, 9, 5, 10, 4, 8, 6]\nnotas = ordenar_mezcla(notas)\nprint(notas)\n", "def merge_sort(items):\n    if len(items) <= 1:\n        return items\n    mid = len(items) // 2\n    left = merge_sort(items[:mid])\n    right = merge_sort(items[mid:])\n    return merge(left, right)\n\n\ndef merge(left, right):\n    result = []\n    i = 0\n    j = 0\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            result.append(left[i])\n            i = i + 1\n        else:\n            result.append(right[j])\n            j = j + 1\n    result.extend(left[i:])\n    result.extend(right[j:])\n    return result\n\n\nmarks = [7, 3, 9, 5, 10, 4, 8, 6]\nmarks = merge_sort(marks)\nprint(marks)\n"], "java": ["import java.util.Arrays;\n\npublic class Main {\n    static int[] ordenarMezcla(int[] lista) {\n        if (lista.length <= 1) {\n            return lista;\n        }\n        int medio = lista.length / 2;\n        int[] izq = ordenarMezcla(Arrays.copyOfRange(lista, 0, medio));\n        int[] der = ordenarMezcla(Arrays.copyOfRange(lista, medio, lista.length));\n        return mezclar(izq, der);\n    }\n\n    static int[] mezclar(int[] izq, int[] der) {\n        int[] resultado = new int[izq.length + der.length];\n        int i = 0;\n        int j = 0;\n        int k = 0;\n        while (i < izq.length && j < der.length) {\n            if (izq[i] <= der[j]) {\n                resultado[k++] = izq[i++];\n            } else {\n                resultado[k++] = der[j++];\n            }\n        }\n        while (i < izq.length) {\n            resultado[k++] = izq[i++];\n        }\n        while (j < der.length) {\n            resultado[k++] = der[j++];\n        }\n        return resultado;\n    }\n\n    public static void main(String[] args) {\n        int[] notas = {7, 3, 9, 5, 10, 4, 8, 6};\n        notas = ordenarMezcla(notas);\n        System.out.println(Arrays.toString(notas));\n    }\n}\n", "import java.util.Arrays;\n\npublic class Main {\n    static int[] mergeSort(int[] items) {\n        if (items.length <= 1) {\n            return items;\n        }\n        int mid = items.length / 2;\n        int[] left = mergeSort(Arrays.copyOfRange(items, 0, mid));\n        int[] right = mergeSort(Arrays.copyOfRange(items, mid, items.length));\n        return merge(left, right);\n    }\n\n    static int[] merge(int[] left, int[] right) {\n        int[] result = new int[left.length + right.length];\n        int i = 0;\n        int j = 0;\n        int k = 0;\n        while (i < left.length && j < right.length) {\n            if (left[i] <= right[j]) {\n                result[k++] = left[i++];\n            } else {\n                result[k++] = right[j++];\n            }\n        }\n        while (i < left.length) {\n            result[k++] = left[i++];\n        }\n        while (j < right.length) {\n            result[k++] = right[j++];\n        }\n        return result;\n    }\n\n    public static void main(String[] args) {\n        int[] marks = {7, 3, 9, 5, 10, 4, 8, 6};\n        marks = mergeSort(marks);\n        System.out.println(Arrays.toString(marks));\n    }\n}\n"]}, {"k": "rapida", "c": "ava", "n": ["Rápida (quicksort)", "Quicksort"], "p": [["notas", "marks", "list"]], "s": false, "py": ["def ordenacion_rapida(lista, inf, sup):\n    if inf < sup:\n        p = particion(lista, inf, sup)\n        ordenacion_rapida(lista, inf, p - 1)\n        ordenacion_rapida(lista, p + 1, sup)\n\n\ndef particion(lista, inf, sup):\n    pivote = lista[sup]\n    i = inf\n    for j in range(inf, sup):\n        if lista[j] <= pivote:\n            lista[i], lista[j] = lista[j], lista[i]\n            i = i + 1\n    lista[i], lista[sup] = lista[sup], lista[i]\n    return i\n\n\nnotas = [7, 3, 9, 5, 10, 4, 8, 6]\nordenacion_rapida(notas, 0, len(notas) - 1)\nprint(notas)\n", "def quick_sort(items, low, high):\n    if low < high:\n        p = partition(items, low, high)\n        quick_sort(items, low, p - 1)\n        quick_sort(items, p + 1, high)\n\n\ndef partition(items, low, high):\n    pivot = items[high]\n    i = low\n    for j in range(low, high):\n        if items[j] <= pivot:\n            items[i], items[j] = items[j], items[i]\n            i = i + 1\n    items[i], items[high] = items[high], items[i]\n    return i\n\n\nmarks = [7, 3, 9, 5, 10, 4, 8, 6]\nquick_sort(marks, 0, len(marks) - 1)\nprint(marks)\n"], "java": ["import java.util.Arrays;\n\npublic class Main {\n    static void ordenacionRapida(int[] lista, int inf, int sup) {\n        if (inf < sup) {\n            int p = particion(lista, inf, sup);\n            ordenacionRapida(lista, inf, p - 1);\n            ordenacionRapida(lista, p + 1, sup);\n        }\n    }\n\n    static int particion(int[] lista, int inf, int sup) {\n        int pivote = lista[sup];\n        int i = inf;\n        for (int j = inf; j < sup; j++) {\n            if (lista[j] <= pivote) {\n                int aux = lista[i];\n                lista[i] = lista[j];\n                lista[j] = aux;\n                i = i + 1;\n            }\n        }\n        int aux = lista[i];\n        lista[i] = lista[sup];\n        lista[sup] = aux;\n        return i;\n    }\n\n    public static void main(String[] args) {\n        int[] notas = {7, 3, 9, 5, 10, 4, 8, 6};\n        ordenacionRapida(notas, 0, notas.length - 1);\n        System.out.println(Arrays.toString(notas));\n    }\n}\n", "import java.util.Arrays;\n\npublic class Main {\n    static void quickSort(int[] items, int low, int high) {\n        if (low < high) {\n            int p = partition(items, low, high);\n            quickSort(items, low, p - 1);\n            quickSort(items, p + 1, high);\n        }\n    }\n\n    static int partition(int[] items, int low, int high) {\n        int pivot = items[high];\n        int i = low;\n        for (int j = low; j < high; j++) {\n            if (items[j] <= pivot) {\n                int tmp = items[i];\n                items[i] = items[j];\n                items[j] = tmp;\n                i = i + 1;\n            }\n        }\n        int tmp = items[i];\n        items[i] = items[high];\n        items[high] = tmp;\n        return i;\n    }\n\n    public static void main(String[] args) {\n        int[] marks = {7, 3, 9, 5, 10, 4, 8, 6};\n        quickSort(marks, 0, marks.length - 1);\n        System.out.println(Arrays.toString(marks));\n    }\n}\n"]}] los rellena build.py. */
